struct Item { value: int }
mut state := []
mut key := 0
while key < 2048 { state = push(state, Item { value: 0 }) key += 1 }
export func snapshot() { return state }
export func edit(amount, limit) {
  mut j := 0
  while j < limit { state[j] = Item { value: amount } j += 1 }
  return amount
}

